package com.xa.pixiv.data;

import android.content.Context;import org.chromium.net.*;import java.io.*;import java.nio.ByteBuffer;import java.util.*;import java.util.concurrent.*;import okhttp3.*;import okio.Buffer;

/** Adapted from Pixiv-Shaft: routes OkHttp API/OAuth calls through Cronet QUIC/HTTP3. */
public final class CronetInterceptor implements Interceptor{
 private static volatile CronetEngine engine;private static final ExecutorService POOL=Executors.newFixedThreadPool(4);private final CronetEngine cronet;
 public CronetInterceptor(Context c){cronet=get(c);}
 private static CronetEngine get(Context c){if(engine==null)synchronized(CronetInterceptor.class){if(engine==null){File dir=new File(c.getCacheDir(),"cronet");dir.mkdirs();String rules="MAP app-api.pixiv.net 104.18.42.239, MAP oauth.secure.pixiv.net 104.18.42.239";engine=new ExperimentalCronetEngine.Builder(c).enableQuic(true).enableHttp2(true).setStoragePath(dir.getAbsolutePath()).addQuicHint("app-api.pixiv.net",443,443).addQuicHint("oauth.secure.pixiv.net",443,443).setExperimentalOptions("{\"HostResolverRules\":{\"host_resolver_rules\":\""+rules+"\"}}").build();}}return engine;}
 @Override public Response intercept(Chain chain)throws IOException{Request request=chain.request();CountDownLatch latch=new CountDownLatch(1);ByteArrayOutputStream out=new ByteArrayOutputStream();Throwable[] error={null};UrlResponseInfo[] info={null};
  UrlRequest.Builder b=cronet.newUrlRequestBuilder(request.url().toString(),new UrlRequest.Callback(){@Override public void onRedirectReceived(UrlRequest r,UrlResponseInfo i,String u){r.followRedirect();}@Override public void onResponseStarted(UrlRequest r,UrlResponseInfo i){info[0]=i;r.read(ByteBuffer.allocateDirect(32768));}@Override public void onReadCompleted(UrlRequest r,UrlResponseInfo i,ByteBuffer x){x.flip();byte[] z=new byte[x.remaining()];x.get(z);out.write(z,0,z.length);x.clear();r.read(x);}@Override public void onSucceeded(UrlRequest r,UrlResponseInfo i){latch.countDown();}@Override public void onFailed(UrlRequest r,UrlResponseInfo i,CronetException e){error[0]=e;latch.countDown();}@Override public void onCanceled(UrlRequest r,UrlResponseInfo i){error[0]=new IOException("Cronet request cancelled");latch.countDown();}},POOL);
  Headers h=request.headers();for(int i=0;i<h.size();i++)b.addHeader(h.name(i),h.value(i));if(request.body()!=null){Buffer buf=new Buffer();request.body().writeTo(buf);b.setUploadDataProvider(UploadDataProviders.create(buf.readByteArray()),POOL);if(request.body().contentType()!=null)b.addHeader("Content-Type",request.body().contentType().toString());}b.setHttpMethod(request.method());UrlRequest call=b.build();call.start();try{if(!latch.await(35,TimeUnit.SECONDS)){call.cancel();return chain.proceed(request);}}catch(InterruptedException e){Thread.currentThread().interrupt();throw new IOException(e);}if(error[0]!=null||info[0]==null)return chain.proceed(request);
  Headers.Builder rh=new Headers.Builder();for(Map.Entry<String,List<String>> e:info[0].getAllHeaders().entrySet())if(!e.getKey().startsWith(":")&&!"content-encoding".equalsIgnoreCase(e.getKey())&&!"content-length".equalsIgnoreCase(e.getKey()))for(String v:e.getValue())try{rh.add(e.getKey(),v);}catch(Exception ignored){}String ct=info[0].getAllHeaders().containsKey("content-type")?info[0].getAllHeaders().get("content-type").get(0):"application/json";String protocol=info[0].getNegotiatedProtocol();Protocol ok="h3".equals(protocol)||"quic".equals(protocol)?Protocol.QUIC:"h2".equals(protocol)?Protocol.HTTP_2:Protocol.HTTP_1_1;return new Response.Builder().request(request).protocol(ok).code(info[0].getHttpStatusCode()).message(info[0].getHttpStatusText()==null?"":info[0].getHttpStatusText()).headers(rh.build()).body(ResponseBody.create(out.toByteArray(),MediaType.parse(ct))).build();}
}
